      id: String((t && t.id) || 't' + (i + 1)),
      role: roles.includes(t && t.role) ? t.role : 'analysis',
      title: String((t && t.title) || 'Task ' + (i + 1)).slice(0, 80),
      instruction: String((t && t.instruction) || '').trim(),
    })).filter((t) => t.instruction);
